<template>
	<header class="app-topbar">
		<div class="topbar-inner container">
			<RouterLink class="brand" :to="{ name: 'chats' }" aria-label="PubChat — на главную"><span class="brand-mark" aria-hidden="true">P</span><span class="brand-name">PubChat</span></RouterLink>
			<nav v-if="isAuthenticated" class="desktop-nav" aria-label="Основная навигация">
				<RouterLink :to="{ name: 'chats' }">Пространства</RouterLink><RouterLink :to="{ name: 'people' }">Люди</RouterLink><RouterLink :to="{ name: 'messenger' }">Сообщения</RouterLink>
			</nav>
