				<RouterLink v-if="isAuthenticated" class="icon-button notification-link" :to="{ name: 'notifications' }" :aria-label="notificationAriaLabel"><i class="far fa-bell" aria-hidden="true"></i><span v-if="unreadNotifications" class="notification-badge" aria-hidden="true">{{ unreadLabel }}</span></RouterLink>
				<button class="icon-button" type="button" :aria-label="currentTheme === 'dark' ? 'Включить светлую тему' : 'Включить тёмную тему'" @click="toggleTheme"><i :class="currentTheme === 'dark' ? 'fas fa-sun' : 'fas fa-moon'" aria-hidden="true"></i></button>
				<div v-if="isAuthenticated" class="persona-menu">
					<button class="persona-trigger" :class="{ 'persona-trigger--open': isDropdownOpen }" type="button" :aria-expanded="isDropdownOpen" aria-haspopup="menu" @click="toggleDropdown"><span class="persona-avatar"><img v-if="currentUser.avatar" :src="avatarUrl" alt="" /><span v-else>{{ avatarFallback }}</span></span><span class="persona-trigger__text"><strong>{{ currentUser.display_name || currentUser.username }}</strong><small>{{ intentLabel }}</small></span><i class="fas fa-chevron-down persona-chevron" aria-hidden="true"></i></button>
					<Transition name="ui-popover"><div v-if="isDropdownOpen" class="persona-dropdown" role="menu">
						<RouterLink role="menuitem" :to="profileRoute" @click="closeDropdown"><i class="fas fa-user-circle"></i><span>Мой образ</span></RouterLink><RouterLink role="menuitem" :to="{ name: 'persona-style' }" @click="closeDropdown"><i class="fas fa-palette"></i><span>Стиль образа</span></RouterLink><RouterLink role="menuitem" :to="{ name: 'achievements' }" @click="closeDropdown"><i class="fas fa-medal"></i><span>Достижения</span></RouterLink><RouterLink role="menuitem" :to="{ name: 'notifications' }" @click="closeDropdown"><i class="far fa-bell"></i><span>Напоминания</span><small v-if="unreadNotifications" class="menu-count">{{ unreadLabel }}</small></RouterLink>
