						<button role="menuitem" type="button" :disabled="isLoggingOut" :aria-busy="isLoggingOut ? 'true' : 'false'" @click="handleLogout"><span v-if="isLoggingOut" class="ui-spinner" aria-hidden="true"></span><i v-else class="fas fa-sign-out-alt" aria-hidden="true"></i><span>{{ isLoggingOut ? 'Выходим…' : 'Выйти' }}</span></button>
