	<nav v-if="isAuthenticated" class="mobile-nav" aria-label="Мобильная навигация"><RouterLink :to="{ name: 'chats' }"><i class="fas fa-comments"></i><span>Пространства</span></RouterLink><RouterLink :to="{ name: 'people' }"><i class="fas fa-user-group"></i><span>Люди</span></RouterLink><RouterLink :to="{ name: 'messenger' }"><i class="fas fa-envelope"></i><span>Чаты</span></RouterLink><RouterLink :to="{ name: 'notifications' }"><i class="far fa-bell"></i><span>Активность</span></RouterLink><RouterLink :to="profileRoute"><i class="fas fa-user-circle"></i><span>Профиль</span></RouterLink></nav>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue';
import { RouterLink, useRouter } from 'vue-router';
import { useStore } from 'vuex';
import { publicAssetUrl } from '@/utils/publicAssetUrl';
const router=useRouter(); const store=useStore(); const currentTheme=ref('light'); const isDropdownOpen=ref(false); const isLoggingOut=ref(false);
const isAuthenticated=computed(()=>store.getters.isAuth); const currentUser=computed(()=>store.getters.getUser||{}); const unreadNotifications=computed(()=>store.getters['notifications/unread']||0); const isAdmin=computed(()=>['admin','superadmin'].includes(currentUser.value.global_role)); const profileRoute=computed(()=>({name:'UserProfile',params:{uid:currentUser.value.uid}}));
const avatarFallback=computed(()=>(currentUser.value.display_name||currentUser.value.username||'?').slice(0,1).toUpperCase()); const avatarUrl=computed(()=>publicAssetUrl(currentUser.value.avatar)); const unreadLabel=computed(()=>unreadNotifications.value>99?'99+':String(unreadNotifications.value)); const notificationAriaLabel=computed(()=>unreadNotifications.value?`Напоминания: ${unreadNotifications.value} непрочитанных`:'Напоминания'); const intentLabel=computed(()=>({open:'Хочу пообщаться',meet:'Открыт знакомствам',games:'Ищу компанию для игры',friends:'Только знакомые',quiet:'Спокойный режим'}[currentUser.value.social_intent]||'В PubChat'));
const toggleDropdown=()=>{isDropdownOpen.value=!isDropdownOpen.value}; const closeDropdown=()=>{isDropdownOpen.value=false}; const handleLogout=async()=>{if(isLoggingOut.value)return; isLoggingOut.value=true; try{await store.dispatch('logout');closeDropdown();await router.replace({name:'login'});}finally{isLoggingOut.value=false;}}; const applyTheme=(theme)=>{document.documentElement.classList.remove('light-theme','dark-theme');document.documentElement.classList.add(`${theme}-theme`);localStorage.setItem('theme',theme);currentTheme.value=theme}; const toggleTheme=()=>applyTheme(currentTheme.value==='dark'?'light':'dark'); onMounted(()=>applyTheme(localStorage.getItem('theme')||'light'));
</script>
